## 2. QUALITY-LF-098 — split `backend/utils/sanitize.ts` (477L, 24-symbol surface)

Constraints honored: pure functions (no I/O, no side effects) → no init-order concerns; **zero imports** → split introduces only intra-package imports; **no parent barrel** → the shim is the sole entry point, so no double-export/cycle risk; **1 test importer via original path** → path untouched, resolves through the shim.

### Layout

```
backend/utils/sanitize.ts        ← LF-065 2-line shim (kept at original path)
backend/utils/sanitize/
  types.ts     — shared option types (zero imports)
  text.ts      — 8 exports (whitespace/control/invisible/bidi + truncate + sanitizeText)
  html.ts      — 4 exports (escape/unescape/strip/sanitizeHtml)
  url.ts       — 2 exports (sanitizeUrl, isSafeUrl)
  path.ts      — 3 exports (filename/slug/path-segment)
  ident.ts     — 5 exports (identifier + 4 case converters)
  email.ts     — 1 export (sanitizeEmail)
  main.ts      — default `sanitize` orchestrator + re-exports (23 named + 1 default = 24)
```

### The 2-line shim (LF-065 rule: `export *` + `export { default }`)

```ts
// backend/utils/sanitize.ts — LF-065 shim: original path preserved.
export * from './sanitize/main';
export { default } from './sanitize/main';
```

> Why `./sanitize/main` and not `./sanitize`? The shim lives at `sanitize.ts`, so `./sanitize` would resolve to *itself* (self-import cycle). The aggregator is named `main.ts` to keep the file-vs-directory promotion unambiguous. `export *` never forwards the default export — that's exactly why the second line exists.

### Module contents (verbatim ports — behavior unchanged)

```ts
// backend/utils/sanitize/types.ts
export type SanitizeMode = 'text' | 'html' | 'url' | 'filename' | 'identifier';
export interface SanitizeOptions {
  mode?: SanitizeMode;
  fallback?: string;
  maxLength?: number;
  allowTags?: string[];
  defaultProtocol?: string;
}
```

```ts
// backend/utils/sanitize/text.ts
export function collapseWhitespace(input: string): string {
  return input.replace(/[\t\n\v\f\r ]+/g, ' ').trim();
}
export function stripControlChars(input: string): string {
  return input.replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F\u007F]/g, '');
}
export function stripInvisibleChars(input: string): string {
  return input.replace(/[\u200B-\u200D\u2060\uFEFF]/g, '');
}
export function stripBidiControls(input: string): string {
  return input.replace(/[\u202A-\u202E\u2066-\u2069]/g, '');
}
export function sanitizeText(input: string, o: { maxLength?: number } = {}): string {
  const out = collapseWhitespace(stripControlChars(stripInvisibleChars(stripBidiControls(input))));
  return o.maxLength === undefined ? out : truncate(out, o.maxLength);
}
export function truncate(input: string, max: number, ellipsis = '…'): string {
  if (max <= 0) return '';
  const chars = Array.from(input);                       // code-point safe (surrogate pairs)
  return chars.length <= max ? input : chars.slice(0, Math.max(0, max - Array.from(ellipsis).length)).join('') + ellipsis;
}
export function normalizeWhitespace(input: string): string {
  return input.replace(/\r\n?/g, '\n').replace(/[ \t]+/g, ' ').replace(/\n[ \t]+/g, '\n').trim();
}
export function stripZeroWidthChars(input: string): string { return stripInvisibleChars(input); }
```

```ts
// backend/utils/sanitize/html.ts
const ESC = { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;', '/': '&#x2F;' };
export function escapeHtml(input: string): string { return input.replace(/[&<>"'/]/g, (c) => ESC[c]); }
export function unescapeHtml(input: string): string {
  return input.replace(/&(#x?[0-9a-fA-F]+|[a-zA-Z]+);/g, (m, e) => {
    if (e.startsWith('#')) {
      const code = /^#x/i.test(e) ? parseInt(e.slice(2), 16) : parseInt(e.slice(1), 10);
      return Number.isNaN(code) ? m : String.fromCodePoint(code);
    }
    return ({ amp: '&', lt: '<', gt: '>', quot: '"', apos: "'" })[e] ?? m;
  });
}
export function stripHtml(input: string): string {
  return input.replace(/<[^>]*>/g, ' ').replace(/&nbsp;/gi, ' ');
}
export function sanitizeHtml(input: string, o: { allowTags?: string[] } = {}): string {
  if (!o.allowTags?.length) return escapeHtml(input);
  const allow = new Set(o.allowTags);
  return input.replace(/<(\/?)([a-zA-Z][a-zA-Z0-9-]*)([^>]*)>/g, (tag, c, name) => allow.has(name) ? tag : escapeHtml(tag));
}
```

```ts
// backend/utils/sanitize/url.ts
const SAFE = new Set(['http:', 'https:', 'mailto:', 'tel:']);
export function sanitizeUrl(input: string, o: { defaultProtocol?: string } = {}): string {
  const t = input.trim();
  if (!t) return '';
  let c = /^[a-zA-Z][a-zA-Z0-9+.-]*:/.test(t) ? t : `${o.defaultProtocol ?? 'https:'}//${t}`;
  if (!SAFE.has(c.slice(0, c.indexOf(':') + 1).toLowerCase())) return '';   // rejects JAVASCRIPT: too
  return c.replace(/[\u0000-\u001F\u007F\u200B-\u200D\uFEFF]/g, '');        // no smuggled control chars
}
export function isSafeUrl(input: string): boolean {
  const t = input.trim();
  return !!t && SAFE.has((t.split(':')[0] ?? '').toLowerCase() + ':');
}
```

```ts
// backend/utils/sanitize/path.ts
export function sanitizeFilename(input: string, o: { maxLength?: number } = {}): string {
  const base = input
    .replace(/[\\/:*?"<>|\u0000-\u001F]/g, '_')
    .replace(/^\.+/, '').replace(/\.+$/, '')          // no .env / no trailing dots (Windows)
    .replace(/\s+/g, ' ').trim() || 'unnamed';        // '..' → 'unnamed', never escapes dir
  return o.maxLength === undefined ? base : base.slice(0, o.maxLength);
}
export function sanitizeSlug(input: string): string {
  return input.normalize('NFKD').replace(/[\u0300-\u036f]/g, '').toLowerCase()
    .replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '');
}
export function sanitizePathSegment(input: string): string {
  return sanitizeFilename(input).replace(/^\.+$/g, '_');
}
```

```ts
// backend/utils/sanitize/ident.ts
const WORDS = /[A-Z]+(?=[A-Z][a-z]|\d|\b)|[A-Z]?[a-z]+|[0-9]+/g;
function words(input: string): string[] {
  return (input.normalize('NFKD').replace(/[\u0300-\u036f]/g, '').replace(/[^a-zA-Z0-9]+/g, ' ').match(WORDS) ?? [])
    .map((w) => w.toLowerCase());
}
const cap = (w: string) => w[0].toUpperCase() + w.slice(1);
export function camelCase(input: string): string {
  const [first = '', ...rest] = words(input);
  return first + rest.map(cap).join('');
}
export function pascalCase(input: string): string { return words(input).map(cap).join(''); }
export function kebabCase(input: string): string { return words(input).join('-'); }
export function snakeCase(input: string): string { return words(input).join('_'); }
export function sanitizeIdentifier(input: string): string {
  const out = camelCase(input);
  return /^[a-zA-Z_$]/.test(out) ? out : `_${out}`;
}
```

```ts
// backend/utils/sanitize/email.ts
const EMAIL = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
export function sanitizeEmail(input: string): string {
  const c = input.trim().toLowerCase().replace(/[\u200B-\u200D\uFEFF]/g, '');
  return EMAIL.test(c) ? c : '';
}
```

```ts
// backend/utils/sanitize/main.ts — orchestrator (default export) + surface re-exports
import { collapseWhitespace, sanitizeText, truncate } from './text';
import { sanitizeHtml, sanitizeUrl, sanitizeFilename, sanitizeIdentifier } from './modules'; // see below
import type { SanitizeOptions } from './types';

function sanitize(input: unknown, options: SanitizeOptions = {}): string {
  if (input === null || input === undefined) return options.fallback ?? '';
  const collapsed = collapseWhitespace(String(input));
  switch (options.mode ?? 'text') {
    case 'html': return sanitizeHtml(collapsed, options);
    case 'url': return sanitizeUrl(collapsed, options);
    case 'filename': return sanitizeFilename(collapsed, options);
    case 'identifier': return sanitizeIdentifier(collapsed, options);
    default: return sanitizeText(collapsed, options);
  }
}
export default sanitize;

// Preserve the full 24-symbol surface at the original path (LF-065):
export * from './text';
export * from './html';
export * from './url';
export * from './path';
export * from './ident';
export * from './email';
```

**Surface math:** named = text(8) + html(4) + url(2) + path(3) + ident(5) + email(1) = **23** named + **1** default `sanitize` = **24 symbols**, exactly matching the original. The original test importer is untouched:

```ts
